import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import API from '../api'; // Use the centralized API
import { useSelector } from 'react-redux'; // Assuming you have Redux for user info

const MyListingsPage = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [deleteSuccess, setDeleteSuccess] = useState(''); // State for delete message

  // Assuming you're using Redux for user authentication
  // If not using Redux, get userInfo from localStorage as in Navbar.js
  const userLogin = useSelector(state => state.userLogin);
  const { userInfo } = userLogin || {}; // Handle case where userLogin might be undefined

  useEffect(() => {
    if (!userInfo) {
      setError('Please log in to view your listings.');
      setLoading(false);
      return;
    }

    const fetchMyProducts = async () => {
      try {
        setLoading(true);
        const config = {
          headers: {
            Authorization: `Bearer ${userInfo.token}`,
          },
        };
        const { data } = await API.get('/api/products/myproducts', config); // New backend endpoint
        setProducts(data);
        setLoading(false);
      } catch (err) {
        console.error(err);
        setError(err.response?.data?.message || 'Failed to fetch your listings.');
        setLoading(false);
      }
    };

    fetchMyProducts();
  }, [userInfo, deleteSuccess]); // Refetch if userInfo changes or a product is deleted

  const deleteProductHandler = async (id) => {
    if (window.confirm('Are you sure you want to delete this listing?')) {
      try {
        const config = {
          headers: {
            Authorization: `Bearer ${userInfo.token}`,
          },
        };
        await API.delete(`/api/products/${id}`, config); // Backend endpoint for deletion
        setDeleteSuccess('Product deleted successfully!');
        // Filter out the deleted product from the state
        setProducts(products.filter(product => product._id !== id));
        setTimeout(() => setDeleteSuccess(''), 3000); // Clear message after 3 seconds
      } catch (err) {
        console.error(err);
        setError(err.response?.data?.message || 'Failed to delete product.');
        setTimeout(() => setError(''), 3000); // Clear message after 3 seconds
      }
    }
  };

  if (!userInfo) {
    return (
      <div className="container mx-auto px-4 py-12 text-center text-xl text-red-500">
        You must be logged in to view your listings.
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-12">
      <h1 className="text-4xl font-bold mb-8 text-center text-stone-gray">My Marketplace Listings</h1>
      {deleteSuccess && (
        <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded relative mb-4 text-center">
          {deleteSuccess}
        </div>
      )}
      {loading ? (
        <div className="text-center">Loading your listings...</div>
      ) : error ? (
        <div className="text-center text-red-500">{error}</div>
      ) : products.length === 0 ? (
        <div className="text-center text-gray-600">You haven't listed any products yet. 
          <Link to="/marketplace/new" className="text-leaf-green hover:underline ml-1">List an item?</Link>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {products.map((product) => (
            <div key={product._id} className="bg-white rounded-lg shadow-lg overflow-hidden flex flex-col transform hover:shadow-xl transition-all duration-300">
              <Link to={`/product/${product._id}`} className="block">
                {/* Image loading fix consideration: Ensure product.image is the correct path */}
                <img src={product.image} alt={product.name} className="w-full h-56 object-cover"/>
              </Link>
              <div className="p-6 flex flex-col flex-grow">
                <h2 className="text-2xl font-bold mb-2 text-forest-green">{product.name}</h2>
                <p className="text-gray-600 mb-4 flex-grow">${product.price}</p>
                <p className="text-gray-500 text-sm mb-4">Listed by: {product.user?.name || 'Unknown'}</p> {/* Display user who listed */}
                <div className="mt-auto flex justify-between items-center">
                  <Link 
                    to={`/product/${product._id}/edit`} // Optional: for editing in the future
                    className="bg-leaf-green text-white px-4 py-2 rounded-md hover:bg-forest-green transition duration-300"
                  >
                    Edit
                  </Link>
                  <button 
                    onClick={() => deleteProductHandler(product._id)}
                    className="bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700 transition duration-300"
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default MyListingsPage;
